def choose_move(observation):
    def sgn(v):
        return (v > 0) - (v < 0)

    def to_xy(item):
        if item is None:
            return None
        if isinstance(item, dict):
            if "position" in item:
                return to_xy(item.get("position"))
            x = item.get("x", item.get("col", item.get("cx")))
            y = item.get("y", item.get("row", item.get("ry")))
            if x is not None and y is not None:
                return [x, y]
            return None
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            return [item[0], item[1]]
        return None

    def move_toward(sx, sy, tx, ty):
        return [sgn(tx - sx), sgn(ty - sy)]

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def nearest(points, sx, sy):
        best = None
        best_d = None
        for p in points:
            q = to_xy(p)
            if q is None:
                continue
            d = abs(q[0] - sx) + abs(q[1] - sy)
            if best is None or d < best_d:
                best = q
                best_d = d
        return best

    def farthest(points, sx, sy):
        best = None
        best_d = None
        for p in points:
            q = to_xy(p)
            if q is None:
                continue
            d = abs(q[0] - sx) + abs(q[1] - sy)
            if best is None or d > best_d:
                best = q
                best_d = d
        return best

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name", obs.get("mode", "resource_collection"))

    self_pos = to_xy(obs.get("self_position", obs.get("position", obs.get("agent_position"))))
    if self_pos is None:
        sx = obs.get("self_x", obs.get("x", 0))
        sy = obs.get("self_y", obs.get("y", 0))
    else:
        sx, sy = self_pos[0], self_pos[1]

    opp_pos = to_xy(obs.get("opponent_position", obs.get("enemy_position", obs.get("target_position"))))
    gw = obs.get("grid_width", obs.get("width", 0))
    gh = obs.get("grid_height", obs.get("height", 0))

    if env == "pursuit_evasion":
        role = obs.get("self_role", obs.get("role", "pursuer"))
        if role == "pursuer":
            if opp_pos is not None:
                return move_toward(sx, sy, opp_pos[0], opp_pos[1])
            enemies = obs.get("opponents", obs.get("enemies", [])) or []
            target = nearest(enemies, sx, sy)
