            target = farthest(corners, sx, sy)
            if target is not None:
                return move_toward(sx, sy, target[0], target[1])
        return [sgn(sx - (opp_pos[0] if opp_pos else 0)), sgn(sy - (opp_pos[1] if opp_pos else 0))]

    if env == "territory_control":
        claimed = obs.get("unclaimed_cells", obs.get("neutral_cells", [])) or []
        targets = claimed
        if not targets:
            targets = obs.get("opponent_territory", obs.get("enemy_territory", [])) or []
        if not targets:
            opp = opp_pos
            if opp is not None:
                return [sgn(sx - opp[0]), sgn(sy - opp[1])]
            return [0, 0]
        target = nearest(targets, sx, sy)
        if target is None:
            return [0, 0]
        return move_toward(sx, sy, target[0], target[1])

    resources = obs.get("resources", obs.get("resource_positions", obs.get("items", []))) or []
    target = nearest(resources, sx, sy)
    if target is not None:
        return move_toward(sx, sy, target[0], target[1])

    if opp_pos is not None:
        return move_toward(sx, sy, opp_pos[0], opp_pos[1])

    return [0, 0]

